const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const value = Object.fromEntries(parts.map((part) => [part.type, part.value]));
return [{ json: { date: `${value.year}-${value.month}-${value.day}` } }];

const s = $json;
const money = (cents) => `₱${(Number(cents || 0) / 100).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const lows = [...s.inventory.critical, ...s.inventory.low].slice(0, 5).map((x) => `• ${x.ingredientName}: ${x.quantity} ${x.unit}`).join('
') || '• None';
const waste = s.waste.entries.slice(0, 5).map((x) => `• ${x.ingredientName}: ${x.quantity} ${x.unit} (${money(x.valueCents)})`).join('
') || '• None logged';
const unmapped = s.recipeCoverage.unmappedProducts.slice(0, 5).map((x) => `• ${x.name}: ${x.quantity}`).join('
') || '• None';
const message = `📊 Restoflow daily — ${s.branch.name} — ${s.date}
Sales: ${money(s.sales.revenueCents)} / ${s.sales.transactions} tickets
Avg ticket: ${money(s.sales.averageTicketCents)}
Food cost: ${money(s.foodCost.cogsCents)} (${Number(s.foodCost.foodCostPercent).toFixed(1)}%)
Recipe coverage: ${Number(s.recipeCoverage.revenuePercent).toFixed(1)}% of revenue

Low / critical stock:
${lows}

Waste (${money(s.waste.totalValueCents)}):
${waste}

Unmapped sales:
${unmapped}

Open requests: ${s.replenishment.openRequests}; in transit: ${s.replenishment.inTransitTransfers}
${$env.RESTOFLOW_BASE_URL}/reports`;
const chatIds = [...new Set([$env.TELEGRAM_OWNER_CHAT_ID, $env.TELEGRAM_MANAGER_CHAT_ID].filter(Boolean))];
return chatIds.map((chatId) => ({ json: { chatId, message } }));
